#ifndef SPEEX_NB3_LSP_H
#define SPEEX_NB3_LSP_H
#include "avr_tables.h"
extern const signed char cdbk_nb[],cdbk_nb_low1[],cdbk_nb_high1[];
static SPEEX_NB3_STAGE_O2 void speex_nb3_lsp_packet(const uint8_t *packet,int16_t *raw,int16_t *out,uint8_t first)
{
    const uint8_t a=((packet[0]&7)<<3)|(packet[1]>>5);
    const uint8_t b=((packet[1]&31)<<1)|(packet[2]>>7);
    const uint8_t c=(packet[2]>>1)&63;
    const int8_t *base=cdbk_nb+10*(unsigned)a;
    const int8_t *low=cdbk_nb_low1+5*(unsigned)b,*high=cdbk_nb_high1+5*(unsigned)c;
    uint8_t i;
    for(i=0;i<5;i++) {
        int16_t quarter=4*((i+1)*128+2*(int16_t)AVR_READ_I8(base+0+i)+(int16_t)AVR_READ_I8(low+i));
        if(first) {raw[i+0]=quarter*4;out[i+0]=0;}
        else out[i+0]=quarter-(raw[i+0]>>2);
    }
    for(i=0;i<5;i++) {
        int16_t quarter=4*((i+6)*128+2*(int16_t)AVR_READ_I8(base+5+i)+(int16_t)AVR_READ_I8(high+i));
        if(first) {raw[i+5]=quarter*4;out[i+5]=0;}
        else out[i+5]=quarter-(raw[i+5]>>2);
    }
}
#endif

